result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_deid.py", "content": "import csv
import datetime as dt
import subprocess
import sys

import pytest

sys.path.insert(0, ".")
from deid_csv import shift_offset, per_patient_hmac  # noqa: E402

IN_CSV = "patients.csv"
SALT_A = "deadbeefcafebabe0123456789abcdef"
SALT_B = "0f1e2d3c4b5a69788796a5b4c3d2e1f0"


def run(out_csv: str, salt: str) -> None:
    subprocess.run(
        [sys.executable, "deid_csv.py", IN_CSV, out_csv, "--salt", salt],
        check=True,
    )


def read_rows(path: str) -> list[dict]:
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def load_input() -> list[dict]:
    return read_rows(IN_CSV)


def test_determinism_same_salt_byte_identical(tmp_path):
    o1, o2 = tmp_path / "a1.csv", tmp_path / "a2.csv"
    run(str(o1), SALT_A)
    run(str(o2), SALT_A)
    assert o1.read_bytes() == o2.read_bytes()


def test_different_salt_changes_pseudonyms(tmp_path):
    oa, ob = tmp_path / "sa.csv", tmp_path / "sb.csv"
    run(str(oa), SALT_A)
    run(str(ob), SALT_B)
    rows_a = {r["patient_id"] for r in read_rows(str(oa))}
    rows_b = {r["patient_id"] for r in read_rows(str(ob))}
    assert len(rows_a) == len(rows_b) == 20
    assert rows_a.isdisjoint(rows_b)


def test_interval_preserved_all_rows(tmp_path):
    out = tmp_path / "out.csv"
    run(str(out), SALT_A)
    src, dst = load_input(), read_rows(str(out))
    assert len(src) == len(dst) == 20
    for s, d in zip(src, dst):
        src_span = (dt.date.fromisoformat(s["discharge_date"])
                    - dt.date.fromisoformat(s["admit_date"])).days
        dst_span = (dt.date.fromisoformat(d["discharge_date"])
                    - dt.date.fromisoformat(d["admit_date"])).days
        assert src_span == dst_span


def test_no_original_id_name_or_full_zip_in_output(tmp_path):
    out = tmp_path / "out.csv"
    run(str(out), SALT_A)
    blob = out.read_text(encoding="utf-8")
    for row in load_input():
        assert row["patient_id"] not in blob
        # name dropped as a column and value absent entirely
        assert row["name"].strip() not in blob
        assert "name" not in blob.lower()
        z = row["zip"].strip()
        if len(z) > 3:
            assert z not in blob


def test_pseudonym_format_and_hmac_derivation():
    for row in load_input():
        digest = per_patient_hmac(bytes.fromhex(SALT_A), row["patient_id"])
        expected = "P" + digest.hex()[:10]
        assert len(expected) == 11 and expected.startswith("P")


def test_offsets_nonzero_and_within_bounds():
    for row in load_input():
        off = shift_offset(per_patient_hmac(bytes.fromhex(SALT_A), row["patient_id"]))
        assert off != 0
        assert -30 <= off <= 30


def test_consistent_shift_per_patient_across_all_dates(tmp_path):
    out = tmp_path / "out.csv"
    run(str(out), SALT_A)
    src, dst = load_input(), read_rows(str(out))
    for s, d in zip(src, dst):
        delta = {
            col: (dt.date.fromisoformat(d[col]) - dt.date.fromisoformat(s[col])).days
            for col in ("dob", "admit_date", "discharge_date")
        }
        assert len(set(delta.values())) == 1  # same offset applied everywhere
